import 'package:flutter/painting.dart';
import 'package:path_drawing/path_drawing.dart';

/// A preset creature picture for the art box.
class CreatureArt {
  const CreatureArt._(this.id, this.label, this.source, this._pathData);

  /// Stable identifier, safe to persist.
  final String id;

  /// What to call it in the dropdown.
  final String label;

  /// Where it came from, relative to the game-icons repository.
  final String source;

  final String _pathData;

  /// The side of the square the path is drawn in.
  static const viewBox = 512.0;

  static final _parsed = <String, Path>{};

  /// The silhouette, parsed once and cached.
  Path get path => _parsed[id] ??= parseSvgPathData(_pathData);

  /// Null for an unknown id — say, a design saved by a newer build with more art.
  static CreatureArt? byId(String? id) {
    if (id == null) return null;
    for (final art in all) {
      if (art.id == id) return art;
    }
    return null;
  }

